    testEnvironment: './jest.env.js',
    transformIgnorePatterns: ['node_modules/(?!(@proton/shared|@proton/components|mutex-browser|pmcrypto|bip39)/)'],
    transform: {
        '^.+\\.(js|tsx?)$': '<rootDir>/jest.transform.js',
